 static let locales:[String]=names.keys.sorted()
 static func text(_ key:String,locale:String)->String{
  guard let index=keys.firstIndex(of:key) else{return key}
  return values[locale]?[index] ?? values["en-US"]?[index] ?? key
 }
 static func translate(_ input:String,locale:String)->String{
  guard let english=values["en-US"],let translated=values[locale] else{return input}
  var result=input
  for index in keys.indices where english[index] != translated[index]{
   result=result.replacingOccurrences(of:english[index],with:translated[index])
  }
  return result
 }
}
